window.TOPICS = [{"id":1,"title":"Constitució espanyola de 1978","official":"La Constitució espanyola de 1.978. Estructura i principis Generals. Drets i deures fonamentals.","area":"General","priority":"Alta","intro":"La Constitució és la norma superior de l’ordenament. Defineix el model d’Estat, els drets de les persones i l’organització dels poders públics. Per al test, és fonamental identificar quin dret apareix en quin article i quina garantia li correspon.","sections":[{"heading":"Estructura i fonaments","body":"Consta d’un preàmbul, un títol preliminar, deu títols i disposicions. L’art. 1 configura Espanya com a Estat social i democràtic de dret; els valors superiors són llibertat, justícia, igualtat i pluralisme polític. La sobirania nacional resideix en el poble espanyol i la forma política és la monarquia parlamentària."},{"heading":"Principis constitucionals","body":"L’art. 9.3 garanteix legalitat, jerarquia normativa, publicitat de les normes, irretroactivitat de disposicions sancionadores no favorables o restrictives de drets individuals, seguretat jurídica, responsabilitat i interdicció de l’arbitrarietat."},{"heading":"Drets i garanties","body":"Art. 14: igualtat; 18: intimitat i protecció de dades; 23: participació i accés en igualtat a funcions públiques; 24: tutela judicial; 25: legalitat sancionadora. L’art. 53 diferencia garanties segons els drets; no tots els drets constitucionals poden protegir-se amb recurs d’empara."},{"heading":"Autonomia local","body":"El títol VIII organitza territorialment l’Estat. Articles 137, 140 i 142: autonomia de municipis, govern municipal i suficiència financera de les hisendes locals."}],"schema":["CONSTITUCIÓ","├─ Títol preliminar → principis (arts. 1–9)","├─ Drets/deures → arts. 10–55","├─ Garanties → art. 53","└─ Organització territorial → títol VIII"],"cards":[{"q":"Quins són els quatre valors superiors de l’ordenament?","a":"Llibertat, justícia, igualtat i pluralisme polític (art. 1.1)."},{"q":"Què protegeix l’article 23?","a":"Participar en assumptes públics i accedir en igualtat a funcions i càrrecs públics."},{"q":"Quin article garanteix l’autonomia municipal?","a":"Article 140; l’article 137 reconeix l’autonomia territorial en general."}],"links":[{"name":"Text consolidat de la Constitució","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229"}],"case":"Davant una sanció municipal, identifica el principi constitucional que exigeix tipificació prèvia de la conducta."},{"id":2,"title":"Organització municipal","official":"Organització municipal: Òrgans necessaris i complementaris. Breu estudi d’aquests. Atribucions dels òrgans necessaris.","area":"General","priority":"Molt alta","intro":"El municipi té territori, població i organització. Els òrgans municipals exerceixen competències diferenciades; les preguntes acostumen a enfrontar atribucions del Ple amb les de l’alcaldia.","sections":[{"heading":"Òrgans necessaris","body":"Alcalde/essa, tinents d’alcalde i Ple existeixen en tots els municipis. La Junta de Govern Local existeix en municipis de més de 5.000 habitants i en els altres quan ho estableix el reglament orgànic o ho acorda el Ple. La composició i règim poden variar en municipis de gran població."},{"heading":"Alcaldia — art. 21 LRBRL","body":"Dirigeix govern i administració municipal, representa l’ajuntament, convoca i presideix Ple i Junta, dirigeix serveis i personal i té funcions en matèria de policia i urgència en els termes legals."},{"heading":"Ple — art. 22 LRBRL","body":"Integrat per regidors i presidit per l’alcalde; controla i fiscalitza els òrgans de govern i adopta acords sobre ordenances, pressupostos, plans i altres matèries atribuïdes per la llei. Algunes atribucions són indelegables."},{"heading":"Junta de Govern, tinents i complements","body":"La Junta assisteix l’alcalde i exerceix les atribucions delegades o que la llei li atribueixi. Els tinents substitueixen l’alcalde per ordre de nomenament. Hi poden haver comissions informatives i altres òrgans complementaris."}],"schema":["MUNICIPI → territori + població + organització","├─ Alcaldia → direcció / representació","├─ Ple → control / decisions plenàries","├─ Junta de Govern → assistència / delegacions","└─ Tinents i comissions → substitució / preparació"],"cards":[{"q":"Qui aprova amb caràcter general el pressupost municipal?","a":"El Ple, sens perjudici dels règims especials previstos per la legislació."},{"q":"La Junta de Govern exerceix totes les funcions de l’alcalde?","a":"No. L’assisteix i només exerceix atribucions legalment pròpies o delegades."},{"q":"Quin article regula les atribucions de l’alcaldia?","a":"Article 21 LRBRL; les del Ple, article 22."}],"links":[{"name":"Bases de règim local","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392"},{"name":"Reglament d’organització","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-33252"}],"case":"Classifica deu competències entre Ple, alcaldia i Junta de Govern, justificant-ne la norma."},{"id":3,"title":"Òrgans col·legiats locals","official":"Funcionament dels òrgans col·legiats locals: Convocatòria i ordre del dia. Debats, votacions i quòrums. Actes i certificats d’acords.","area":"General","priority":"Molt alta","intro":"No confonguis tres qüestions diferents: convocar una sessió, constituir vàlidament l’òrgan i adoptar un acord. El règim dels òrgans locals es regula especialment a la LRBRL i al ROF.","sections":[{"heading":"Sessions i convocatòries","body":"Les sessions del Ple poden ser ordinàries, extraordinàries o extraordinàries urgents. Com a regla general, la convocatòria ordinària o extraordinària s’ha de fer almenys amb dos dies hàbils d’antelació, tret de les extraordinàries urgents, la urgència de les quals s’ha de ratificar."},{"heading":"Constitució — art. 46 LRBRL","body":"Per constituir-se vàlidament, en règim general cal assistència d’un terç del nombre legal de membres, que mai pot ser inferior a tres, i presència de presidència i secretaria o substituts legals. Aquest quòrum s’ha de mantenir durant tota la sessió."},{"heading":"Debat i votació","body":"Les propostes se sotmeten a debat i votació. La majoria simple és més vots afirmatius que negatius; la majoria absoluta requereix més de la meitat del nombre legal de membres. Algunes decisions exigeixen majoria absoluta o altres majories legalment previstes."},{"heading":"Actes i certificacions","body":"La secretaria aixeca acta amb dades bàsiques de la sessió, assistents, assumptes i acords. Les certificacions acrediten acords i les expedeix la secretaria en els termes de la normativa aplicable."}],"schema":["SESSIÓ COL·LEGIADA","Convocatòria → ordre del dia","Constitució → quòrum d’assistència","Debat → votació → majoria requerida","Secretaria → acta i certificacions"],"cards":[{"q":"Què diferencia quòrum i majoria?","a":"Quòrum = assistència mínima per constituir l’òrgan. Majoria = vots necessaris per aprovar un acord."},{"q":"Una sessió extraordinària urgent pot convocar-se sense dos dies hàbils?","a":"Sí, però la urgència s’ha de sotmetre a ratificació segons el règim aplicable."},{"q":"Qui aixeca l’acta del Ple?","a":"La secretaria de la corporació o qui la substitueixi legalment."}],"links":[{"name":"LRBRL, arts. 46–47","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392"},{"name":"ROF","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-33252"}],"case":"Amb 21 regidors, distingeix quants membres fan falta per constituir el Ple i quants vots per majoria absoluta."},{"id":4,"title":"Procediment administratiu comú","official":"El procediment administratiu comú: Concepte d’interessat. Fases del procediment.","area":"General","priority":"Molt alta","intro":"La Llei 39/2015 regula com l’Administració inicia, tramita, decideix i executa els procediments. En exàmens municipals és clau distingir fases del procediment, tràmits concrets i maneres de finalització.","sections":[{"heading":"Interessats — art. 4","body":"Són interessats els qui promouen el procediment com a titulars de drets o interessos legítims; els qui, sense iniciar-lo, tenen drets susceptibles d’afectació; i els qui tenen interessos legítims que poden resultar afectats i hi compareixen abans de la resolució definitiva."},{"heading":"Iniciació i ordenació","body":"S’inicia d’ofici o a sol·licitud. La iniciació delimita l’objecte; l’ordenació impulsa d’ofici els tràmits, en respecta l’ordre i aplica els principis de celeritat i simplificació."},{"heading":"Instrucció","body":"Inclou al·legacions, prova quan pertoqui, informes i tràmit d’audiència. Aquest últim no és automàtic en tots els supòsits: hi ha excepcions legalment previstes."},{"heading":"Finalització i execució","body":"Pot acabar per resolució, desistiment, renúncia, caducitat o impossibilitat material sobrevinguda, segons el cas. L’execució correspon a una fase posterior i ha de respectar els requisits legals."},{"heading":"Terminis i relació electrònica","body":"Els dies són hàbils llevat que s’indiqui que són naturals; s’exclouen dissabtes, diumenges i festius. Distingir obligats electrònics (art. 14), dret de l’interessat (art. 53), notificacions i silenci administratiu."}],"schema":["PROCEDIMENT","1. Iniciació → d’ofici / sol·licitud","2. Ordenació → impuls i tramitació","3. Instrucció → prova / informes / audiència","4. Finalització → resolució i altres formes","5. Execució → compliment de la decisió"],"cards":[{"q":"Què és un interessat?","a":"Persona física o jurídica amb drets o interessos legítims en les circumstàncies de l’art. 4 LPAC."},{"q":"La prova pertany a quina fase?","a":"A la instrucció; no és una forma de finalització."},{"q":"Els dissabtes compten com a dies hàbils?","a":"No, a efectes del còmput general de terminis de la Llei 39/2015."}],"links":[{"name":"Llei 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"}],"case":"Explica quin tràmit faries abans de resoldre un expedient municipal quan apareixen fets desfavorables per a l’interessat."},{"id":5,"title":"Contractació administrativa","official":"Contractació administrativa: Concepte de contracte administratiu. Diferents tipus de contractes administratius. Contractes subjectes i no subjectes a regulació harmonitzada.","area":"General","priority":"Mitjana","intro":"La Llei 9/2017 diferencia contractes segons objecte, naturalesa jurídica i règim de publicitat. Per respondre bé, evita confondre contracte administratiu amb qualsevol contracte del sector públic.","sections":[{"heading":"Objecte i tipologia","body":"Hi ha contractes d’obres, concessió d’obres, concessió de serveis, subministraments i serveis. La concessió exigeix transferència de risc operacional al concessionari; sense aquesta transferència, no n’hi ha prou per parlar de concessió."},{"heading":"Contractes administratius i privats","body":"La qualificació depèn de l’entitat contractant i de l’objecte segons la LCSP. Les administracions públiques formalitzen contractes típics administratius, amb les excepcions i contractes privats previstos per llei."},{"heading":"Regulació harmonitzada","body":"Els contractes subjectes a regulació harmonitzada (SARA) compleixen condicions de tipologia, poder adjudicador i valors estimats/llindars europeus. Els llindars varien amb actualitzacions; cal consultar l’import vigent, no memoritzar-ne un d’antic."},{"heading":"Procediment","body":"Necessitat i justificació, expedient i plecs, publicitat quan pertoqui, selecció, adjudicació, formalització i execució. Diferencia valor estimat, pressupost base de licitació i preu final."}],"schema":["CONTRACTES PÚBLICS","├─ Per objecte → obres / serveis / subministrament / concessions","├─ Per naturalesa → administratius / privats","├─ Per règim UE → SARA / no SARA","└─ Cicle → preparació / adjudicació / execució"],"cards":[{"q":"Què diferencia una concessió d’un contracte de serveis?","a":"La transferència efectiva del risc operacional al concessionari."},{"q":"SARA és sinònim de contracte administratiu?","a":"No. SARA és un règim lligat a tipologia i llindars; la naturalesa administrativa és una classificació diferent."},{"q":"El valor estimat del contracte inclou IVA?","a":"No; el valor estimat es calcula sense IVA segons la LCSP."}],"links":[{"name":"Llei de contractes del sector públic","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"}],"case":"Classifica si el manteniment anual del web municipal és contracte de serveis i què ha de contenir el plec tècnic."},{"id":6,"title":"Gestió dels serveis públics","official":"Formes de gestió del servei públic. Gestió directa i indirecta.","area":"General","priority":"Mitjana","intro":"Els serveis locals poden prestar-se a través d’organització pròpia o mitjançant formes de gestió indirecta. La decisió exigeix valorar eficiència, sostenibilitat i competència municipal.","sections":[{"heading":"Gestió directa","body":"L’article 85 LRBRL contempla la gestió per la pròpia entitat local, organisme autònom local, entitat pública empresarial local o societat mercantil local de capital íntegrament públic, amb condicions específiques per a determinades formes."},{"heading":"Gestió indirecta","body":"Es desenvolupa mitjançant les formes contractuals admeses per la normativa de contractació, especialment la concessió de serveis quan concorre risc operacional. No és correcte equiparar qualsevol encàrrec extern a una concessió."},{"heading":"Límits i decisió","body":"La titularitat i responsabilitat sobre el servei no desapareixen pel fet de contractar-ne la prestació. Distingir competència, titularitat, mode de gestió, explotació i control del servei."}],"schema":["SERVEI PÚBLIC LOCAL","├─ Gestió directa → ajuntament / ens o societat pública","└─ Gestió indirecta → contractació amb tercer","En tots dos casos → control públic i legalitat"],"cards":[{"q":"Una societat mercantil municipal de capital íntegrament públic és gestió directa?","a":"Sí, si encaixa en els requisits de l’art. 85 LRBRL."},{"q":"Gestió indirecta equival sempre a concessió?","a":"No; cal qualificar el contracte per l’objecte i pel risc operacional."},{"q":"Externalitzar el servei elimina el control municipal?","a":"No, el municipi conserva les seves responsabilitats i potestats de control."}],"links":[{"name":"LRBRL, art. 85","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392"},{"name":"LCSP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"}],"case":"Compara dues opcions de gestió d’un servei informàtic municipal i diferencia suport tècnic extern de concessió."},{"id":7,"title":"Drets i deures dels empleats públics","official":"Drets i deures dels empleats públics.","area":"General","priority":"Mitjana","intro":"El TREBEP defineix classes de personal, drets, deures, principis ètics i règim disciplinari. És freqüent que una pregunta barregi drets individuals amb drets col·lectius o tipus de personal.","sections":[{"heading":"Classes de personal","body":"Funcionaris de carrera, interins, personal laboral (fix, per temps indefinit o temporal) i personal eventual. El personal directiu professional té una regulació particular: no s’ha de confondre automàticament amb una cinquena classe en la llista de l’art. 8."},{"heading":"Drets","body":"Drets individuals com a carrera professional, formació, defensa jurídica en supòsits previstos, retribucions i vacances. Drets individuals exercits col·lectivament: llibertat sindical, negociació col·lectiva, vaga i reunió, amb límits legals."},{"heading":"Deures i conducta","body":"Diligència, objectivitat, integritat, imparcialitat, confidencialitat, servei a l’interès general, respecte a les dades i ús adequat dels recursos públics."},{"heading":"Règim disciplinari","body":"Responsabilitat, tipificació de faltes i sancions, proporcionalitat i procediment. No confonguis incompatibilitat, abstenció i falta disciplinària: poden tenir fonaments diferents."}],"schema":["PERSONAL PÚBLIC → art. 8 TREBEP","├─ Carrera / interí / laboral / eventual","├─ Drets → individuals i col·lectius","├─ Deures → principis ètics i de conducta","└─ Responsabilitat → disciplina"],"cards":[{"q":"Quines són les quatre classes d’empleats públics de l’art. 8?","a":"Funcionaris de carrera, interins, personal laboral i eventual."},{"q":"La confidencialitat és un deure de l’empleat públic?","a":"Sí, amb especial incidència en informació personal i expedients."},{"q":"El personal eventual ocupa la plaça per nomenament de confiança o assessorament especial?","a":"Sí, amb les condicions legals de l’art. 12 TREBEP."}],"links":[{"name":"TREBEP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719"}],"case":"Com actuaries si un treballador demana accedir a expedients municipals sense necessitat funcional?"},{"id":8,"title":"Hisendes locals","official":"Hisendes locals: Recursos dels municipis. Els tributs propis dels municipis: Impostos, taxes i contribucions especials.","area":"General","priority":"Mitjana","intro":"El text refós de la Llei reguladora de les hisendes locals classifica els ingressos i diferencia tres figures tributàries: impostos, taxes i contribucions especials.","sections":[{"heading":"Recursos municipals","body":"Ingressos patrimonials i de dret privat; tributs propis; participació en tributs de l’Estat i comunitats autònomes; subvencions; preus públics; operacions de crèdit; multes i sancions, entre altres."},{"heading":"Impostos","body":"Exigits sense contraprestació directa. Obligatoris municipals: IBI, IAE i IVTM. Potestatius: ICIO i IIVTNU (plusvàlua municipal), segons el règim legal."},{"heading":"Taxes i contribucions especials","body":"Taxa: utilització privativa o aprofitament especial del domini públic, o prestació de serveis/activitats administratives en els supòsits legals. Contribució especial: benefici especial o augment de valor produït per obres públiques o establiment/ampliació de serveis."},{"heading":"Preus públics","body":"No són tributs. Es diferencien de taxes atenent les circumstàncies de voluntarietat i prestació per sector privat, segons regulació."}],"schema":["RECURSOS MUNICIPALS","├─ Tributs → impostos / taxes / contribucions especials","├─ Preus públics (no tribut)","├─ Transferències i subvencions","└─ Patrimoni / crèdit / sancions"],"cards":[{"q":"Quins impostos municipals són obligatoris?","a":"IBI, IAE i IVTM."},{"q":"Quin tribut s’associa a un benefici especial per una obra pública?","a":"La contribució especial."},{"q":"El preu públic és un tribut?","a":"No; és una categoria d’ingrés de dret públic diferent dels tributs."}],"links":[{"name":"Text refós d’hisendes locals","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-4214"}],"case":"Distingeix el tribut d’una llicència urbanística, el d’una obra que beneficia especialment uns immobles i un preu públic."},{"id":9,"title":"Ordinadors personals i maquinari","official":"Ordinadors personals. Arquitectura. Tipus i característiques. Instal·lació i configuració de components de maquinari.","area":"Sistemes","priority":"Mitjana","intro":"Entendre com cooperen CPU, RAM, emmagatzematge, placa base i perifèrics permet diagnosticar incidències reals de suport informàtic municipal.","sections":[{"heading":"Arquitectura","body":"CPU executa instruccions; RAM emmagatzema dades temporals volàtils; SSD/HDD són persistents; busos i chipset/controladors connecten components. UEFI inicialitza el maquinari i facilita l’arrencada del sistema."},{"heading":"Tipus i rendiment","body":"Compara equips de sobretaula, portàtils, mini-PC, estacions de treball. CPU: nuclis/fils; memòria: capacitat i velocitat; SSD: interfície SATA vs NVMe/PCIe; pantalles i GPU segons necessitat."},{"heading":"Instal·lació segura","body":"Comprovar compatibilitat, electricitat i descàrrega electrostàtica, cablejat, controladors, actualitzacions i diagnosi. Separar avaria de hardware de problema de SO o xarxa."},{"heading":"Diagnosi","body":"Si un PC no arrenca: alimentació, POST/UEFI, RAM, disc, registres i perifèrics. Protegir dades abans d’operacions irreversibles."}],"schema":["ORDINADOR","Entrada → CPU ↔ RAM ↔ emmagatzematge","Placa base i busos → interconnexió","UEFI → arrencada del sistema operatiu","Diagnosi → maquinari / controladors / programari"],"cards":[{"q":"La RAM conserva dades sense corrent?","a":"No; és memòria volàtil."},{"q":"Quina interfície s’utilitza sovint amb SSD NVMe?","a":"PCI Express (PCIe), diferent d’un SSD SATA."},{"q":"Què comprova el POST?","a":"Funcions bàsiques del maquinari durant l’arrencada."}],"links":[],"case":"Un ordinador de l’OAC no inicia Windows: proposa una seqüència de comprovacions sense posar en risc les dades."},{"id":10,"title":"GNU/Linux i programari lliure","official":"Sistemes Operatius GNU/Linux. Conceptes de programari lliure. Distribucions.","area":"Sistemes","priority":"Molt alta","intro":"GNU/Linux és central en les preguntes tècniques: ordres, permisos, processos, serveis i diferències entre distribucions. És un sistema tipus Unix amb kernel Linux i un conjunt de programes d’usuari.","sections":[{"heading":"Programari lliure","body":"Les quatre llibertats fan referència a executar, estudiar/modificar, redistribuir i distribuir versions modificades. Codi obert no significa necessàriament gratuït; cal respectar llicències com GPL o MIT."},{"heading":"Fitxers i ordres","body":"`pwd`, `ls -la`, `cd`, `cp`, `mv`, `rm`, `mkdir`, `find`, `grep`, `cat`, `less`, `tail`, `chmod`, `chown`, `ps`, `top`, `df`, `du`. Rutes absolutes comencen a `/`; els noms distingeixen majúscules i minúscules."},{"heading":"Permisos","body":"Tres categories: usuari, grup, altres; tres drets: lectura=4, escriptura=2, execució=1. `chmod 750` = propietari rwx, grup r-x i altres sense permisos. En directoris, execució permet travessar-los."},{"heading":"Gestió de sistema","body":"`sudo`, comptes i grups; processos i senyals (`kill`); paquets segons distribució (`apt`, `dnf`); serveis amb `systemctl`; registres amb `journalctl` o `/var/log`, sense assumir que tots els sistemes són iguals."}],"schema":["LINUX","├─ Sistema de fitxers → /, /home, /etc, /var","├─ Permisos → usuari / grup / altres (rwx)","├─ Processos → ps / top / kill","└─ Serveis i logs → systemctl / journalctl"],"cards":[{"q":"Què significa chmod 640?","a":"Propietari lectura i escriptura; grup només lectura; altres cap permís."},{"q":"Quina comanda mostra el directori actual?","a":"`pwd`."},{"q":"Linux i programari lliure són sinònims de gratuït?","a":"No: la llibertat de programari no és el preu."}],"links":[{"name":"Manuals d’Ubuntu","url":"https://ubuntu.com/tutorials/command-line-for-beginners"}],"case":"Un servei Linux no arrenca: indica com consultar-ne estat, logs i permisos abans de reiniciar-lo."},{"id":11,"title":"Windows 11 Professional","official":"Sistemes Operatius Windows 11 Professional: Conceptes bàsics, instal·lació i configuració.","area":"Sistemes","priority":"Mitjana","intro":"Windows 11 Pro és un sistema operatiu client utilitzat per a entorns corporatius. El suport municipal implica instal·lació, comptes, permisos, xarxa, actualitzacions i diagnòstic.","sections":[{"heading":"Instal·lació i arrencada","body":"Comprovar requisits, UEFI/Secure Boot, TPM 2.0 i espai; fer còpia abans de migrar. Diferenciar instal·lació neta i actualització. Llicència i activació es gestionen segons l’entorn corporatiu."},{"heading":"Identitat i permisos","body":"Comptes locals, de domini i identitats corporatives. NTFS permet ACL i permisos més granulars que la simple compartició. Concepte de mínim privilegi, UAC i BitLocker."},{"heading":"Administració","body":"Configuració, Administrador de dispositius, Gestió de discos, Visor d’esdeveniments, serveis, `ipconfig`, `ping`, `sfc`, `DISM` i eines de PowerShell per diagnosi."},{"heading":"Seguretat i manteniment","body":"Windows Update, Microsoft Defender, protecció de l’equip, còpies de seguretat, xifrat, control d’aplicacions i gestió centralitzada quan existeix."}],"schema":["WINDOWS 11 PRO","Instal·lació → UEFI / TPM / disc","Usuaris → permisos NTFS / UAC","Administració → esdeveniments / serveis","Manteniment → actualitzacions / còpia / BitLocker"],"cards":[{"q":"Què és BitLocker?","a":"Tecnologia de xifrat de volums de Microsoft."},{"q":"Permís NTFS i permís de compartició són el mateix?","a":"No. Són capes de control diferents que poden aplicar-se conjuntament."},{"q":"On consultaries errors del sistema?","a":"Al Visor d’esdeveniments, i amb eines de diagnosi segons incidència."}],"links":[{"name":"Documentació Microsoft Windows","url":"https://learn.microsoft.com/windows/"}],"case":"Un usuari accedeix a una carpeta compartida però no pot editar un document: analitza permisos NTFS i de compartició."},{"id":12,"title":"Còpies de seguretat i recuperació","official":"Còpies de seguretat. Tipus. Recuperació i restauració. Continuïtat de negoci i entorn de recuperació de desastres. Estratègies i bones pràctiques.","area":"Sistemes","priority":"Alta","intro":"Les còpies s’han de dissenyar per poder restaurar dades i serveis, no només per acumular arxius. El test sol confondre còpia completa, incremental, diferencial i replicació.","sections":[{"heading":"Tipus de còpia","body":"Completa: totes les dades; incremental: canvis des de l’última còpia de qualsevol tipus; diferencial: canvis des de l’última completa. Recuperar una incremental pot exigir cadena de còpies, mentre que la diferencial necessita la completa i l’última diferencial."},{"heading":"Regla 3-2-1 i immutabilitat","body":"Disposar de 3 còpies, en 2 tipus de suport, 1 fora de l’emplaçament, amb estratègies modernes com còpia immutable o aïllada. La replicació no substitueix una còpia: pot replicar l’esborrament o ransomware."},{"heading":"Continuïtat i DRP","body":"BCP = continuïtat del negoci; DRP = recuperació tecnològica davant desastre. RPO = pèrdua màxima de dades acceptable (temps); RTO = temps objectiu per recuperar el servei."},{"heading":"Proves i governança","body":"Definir periodicitat, retenció, xifrat i permisos. Provar restauracions, documentar responsables i fer simulacions. Una còpia que no es pot restaurar no compleix l’objectiu."}],"schema":["PROTECCIÓ DE DADES","Planificar RPO/RTO → triar còpies","Completa / incremental / diferencial","3-2-1 + aïllament / xifrat","Verificar → provar restauració → revisar"],"cards":[{"q":"RPO és el temps que triguem a recuperar el servei?","a":"No. RPO mesura la pèrdua màxima de dades; RTO és el temps objectiu de recuperació."},{"q":"Una rèplica sincronitzada elimina la necessitat de backup?","a":"No; pot reproduir corrupcions o esborraments."},{"q":"Què guarda una còpia diferencial?","a":"Canvis des de l’última còpia completa."}],"links":[],"case":"Un ransomware xifra el servidor de registre: ordena detecció, contenció, recuperació i validació de dades."},{"id":13,"title":"Models OSI i TCP/IP","official":"Models de referència per a la comunicació de sistemes oberts: OSI i TCP/IP. Capes, funcionalitats i protocols.","area":"Xarxes","priority":"Alta","intro":"El model OSI té set capes i el model TCP/IP s’explica habitualment amb quatre o cinc. Serveixen per localitzar on falla una comunicació.","sections":[{"heading":"Capes OSI","body":"1 física: senyals; 2 enllaç: trames i MAC; 3 xarxa: IP i encaminament; 4 transport: TCP/UDP i ports; 5 sessió; 6 presentació; 7 aplicació: protocols utilitzats per programes."},{"heading":"TCP/IP","body":"Accés a xarxa, Internet, transport i aplicació. IP és no orientat a connexió; TCP proporciona connexió i lliurament fiable/ordenat; UDP evita part de la sobrecàrrega i és adequat a altres casos."},{"heading":"Protocols i diagnosi","body":"DNS resol noms; DHCP assigna configuració IP; HTTP/HTTPS transporta web sobre TCP (amb evolucions com HTTP/3 sobre QUIC/UDP); ICMP s’usa en diagnosi; ARP associa IPv4/MAC en LAN."},{"heading":"Proves","body":"`ping`, `traceroute`/`tracert`, `nslookup`/`dig`, `ipconfig`/`ip addr`, `ss` i eines de captura poden acotar l’avaria per capes."}],"schema":["OSI 7 → APLICACIÓ","7 Aplicació · 6 Presentació · 5 Sessió","4 Transport → TCP/UDP, ports","3 Xarxa → IP, encaminament","2 Enllaç → MAC, Ethernet","1 Física → cables, senyal"],"cards":[{"q":"A quina capa OSI treballa IP?","a":"Capa 3, xarxa."},{"q":"TCP i UDP corresponen a quina capa?","a":"Transport, capa 4."},{"q":"DNS és el mateix que DHCP?","a":"No. DNS resol noms i DHCP distribueix configuració de xarxa."}],"links":[{"name":"Introducció de Cloudflare a OSI","url":"https://www.cloudflare.com/learning/ddos/glossary/open-systems-interconnection-model-osi/"}],"case":"Un equip rep IP per DHCP però no obre un portal per nom: descarta capes i prova DNS."},{"id":14,"title":"Xarxes d’àrea local","official":"Xarxes d’àrea local: Conceptes bàsics, topologies (bus, anell, estrella, ...).","area":"Xarxes","priority":"Mitjana","intro":"Una LAN interconnecta dispositius d’un àmbit limitat i requereix planificar topologia, adreçament, commutació, segmentació i disponibilitat.","sections":[{"heading":"Topologies","body":"Bus: medi compartit; anell: nodes connectats en circuit; estrella: nodes connectats a un equip central; malla: múltiples camins. La topologia física i la lògica poden no coincidir."},{"heading":"Switch i encaminador","body":"Switch de capa 2 commuta trames segons MAC; router interconnecta xarxes IP. Un commutador de capa 3 pot fer funcions d’encaminament. Un hub repeteix senyals i no equival a switch."},{"heading":"VLAN i IP","body":"Una VLAN delimita dominis de difusió a capa 2. Una subxarxa IP s’identifica per prefix/màscara. Per comunicar VLAN diferents normalment cal encaminament entre VLAN."},{"heading":"Operació segura","body":"Cablejat estructurat, etiquetatge, documentació, redundància, control d’accés i monitoratge. Separació de xarxes de convidats, gestió interna i equips crítics."}],"schema":["LAN","Topologia física → estrella / bus / anell / malla","Commutació → switch i MAC","Segmentació → VLAN i subxarxes","Interconnexió → router / encaminament"],"cards":[{"q":"Quin dispositiu usa habitualment una taula MAC?","a":"El switch Ethernet."},{"q":"Una VLAN és equivalent a una subxarxa IP?","a":"No, són conceptes de capes diferents, encara que solen mapar-se."},{"q":"Topologia en estrella: quin és el punt central?","a":"Habitualment un switch."}],"links":[],"case":"Dissenya separació lògica entre OAC, personal intern i Wi-Fi de visitants."},{"id":15,"title":"Xarxes sense fils","official":"Xarxes sense fils. Tipus i característiques. Estàndards, seguretat i fiabilitat.","area":"Xarxes","priority":"Mitjana","intro":"Les xarxes Wi-Fi aporten mobilitat, però el medi radioelèctric és compartit i pot patir interferències. Seguretat i cobertura no són el mateix.","sections":[{"heading":"Estàndards","body":"Família IEEE 802.11: generacions comercials Wi‑Fi 4/5/6/6E/7 segons bandes i característiques. Les bandes de 2,4, 5 i 6 GHz tenen diferències de cobertura, canals i disponibilitat segons dispositius i país."},{"heading":"Seguretat","body":"Evitar WEP i WPA antic. Prioritzar WPA2-AES o WPA3 quan sigui compatible. En entorns corporatius es pot usar 802.1X/EAP i servidor RADIUS, amb credencials per usuari en lloc d’una clau compartida."},{"heading":"Fiabilitat i diagnosi","body":"Analitzar potència de senyal, interferències, congestió, amplada de canal, roaming, densitat de punts d’accés i posicionament físic. Una bona senyal no garanteix accés a Internet si DNS o DHCP fallen."},{"heading":"Segmentació","body":"Separar SSID de convidats i corporatiu, limitar accés lateral, aïllar clients quan convingui i supervisar punts d’accés no autoritzats."}],"schema":["WI-FI","Ràdio → bandes / canals / interferència","Autenticació → WPA2/3 / 802.1X","Xarxa → DHCP/DNS / VLAN","Operació → cobertura / roaming / monitoratge"],"cards":[{"q":"És segur WEP?","a":"No, està obsolet i és insegur."},{"q":"Quin servei centralitza habitualment autenticació 802.1X?","a":"RADIUS."},{"q":"Canviar el SSID xifra el trànsit?","a":"No; el SSID és un identificador de xarxa, no un mecanisme de xifrat."}],"links":[],"case":"Una sala d’actes té Wi-Fi saturat: proposa comprovacions d’interferències i segmentació."},{"id":16,"title":"Internet, intranet i riscos","official":"Internet. Aplicacions: cercadors, correu electrònic, serveis de directori. Intranet i extranet: Definició i aplicacions. Riscos de la xarxa (virus, hackers, espies, pop-ups).","area":"Xarxes","priority":"Mitjana","intro":"Internet interconnecta xarxes globals; una intranet és un servei restringit a l’organització i una extranet permet accés delimitat a tercers. Cal dominar serveis i riscos comuns.","sections":[{"heading":"Serveis","body":"Web i cercadors, DNS, correu (SMTP per enviament; IMAP/POP3 per accés), serveis de directori com LDAP/Active Directory, transferència d’arxius i eines de col·laboració."},{"heading":"Intranet i extranet","body":"Intranet: continguts interns per al personal. Extranet: zona restringida accessible a proveïdors o altres actors autoritzats. No depèn necessàriament del lloc físic: VPN i autenticació permeten accés segur remot."},{"heading":"Amenaces","body":"Malware (virus, troians, spyware, ransomware), phishing, enginyeria social, extensions malicioses, finestres emergents enganyoses i atacants que exploten vulnerabilitats. El terme «hacker» no implica sempre activitat delictiva."},{"heading":"Prevenció","body":"Pedaços, MFA, navegació segura, filtres de correu, còpies, EDR/antivirus, mínim privilegi i formació. La protecció tècnica no substitueix la verificació d’identitat i la prudència amb fitxers adjunts."}],"schema":["SERVEIS DE XARXA","Internet → web / correu / DNS / directoris","Intranet → personal autoritzat","Extranet → col·laboradors externs autoritzats","Riscos → malware / phishing / explotació","Defensa → actualitzacions / MFA / còpies"],"cards":[{"q":"SMTP s’utilitza principalment per a què?","a":"Per transferir/enviar correu electrònic entre clients/servidors i servidors."},{"q":"Intranet i extranet són el mateix?","a":"No: intranet és interna; extranet dona accés delimitat a actors externs."},{"q":"Quina és una mesura eficaç contra robatori de contrasenyes?","a":"MFA, juntament amb contrasenyes robustes i detecció de phishing."}],"links":[],"case":"Un treballador rep un correu que demana introduir la contrasenya municipal: explica protocol de resposta."},{"id":17,"title":"Seguretat en xarxes i criptografia","official":"Seguretat en Xarxes i Criptografia. Sistemes de defensa en profunditat: Tallafocs (Firewalls), IDS/IPS i VPN. Fonaments de criptografia: xifratge simètric i asimètric. Gestió de vulnerabilitats i proves de penetració.","area":"Seguretat","priority":"Molt alta","intro":"La seguretat de xarxa consisteix a aplicar controls complementaris i gestionar riscos. És essencial diferenciar un tallafoc, un IDS, un IPS, una VPN, el xifrat i la signatura digital.","sections":[{"heading":"Defensa en profunditat","body":"Aplicar controls a perímetre, xarxa, identitat, endpoint, aplicació i dades. Tallafoc filtra trànsit segons regles; IDS detecta i alerta; IPS pot bloquejar activament. Segmentació, MFA i registre d’esdeveniments completen la defensa."},{"heading":"VPN i canals segurs","body":"Una VPN crea un túnel protegit entre punts; no converteix en fiable un dispositiu infectat. TLS aporta protecció de comunicacions amb negociació criptogràfica i autenticació del servidor mitjançant certificats."},{"heading":"Criptografia","body":"Simètrica: mateixa clau secreta per xifrar/desxifrar (p. ex. AES); asimètrica: parella de clau pública i privada (p. ex. RSA o criptografia de corbes el·líptiques). Hash criptogràfic no és xifratge reversible."},{"heading":"Vulnerabilitats i pentest","body":"Inventariar actius, detectar CVE, classificar risc, aplicar pedaços i verificar. Escàner de vulnerabilitats automatitzat no equival a prova de penetració, que valida vies d’explotació amb autorització i abast definits."}],"schema":["DEFENSA EN PROFUNDITAT","Xarxa → Firewall + segmentació + IDS/IPS","Identitat → MFA / mínim privilegi","Dades → xifrat + còpia","Vulnerabilitats → detectar → prioritzar → corregir → verificar"],"cards":[{"q":"IDS i IPS: diferència clau?","a":"IDS detecta/alerta; IPS també pot impedir el trànsit sospitós."},{"q":"Una funció hash és un xifrat reversible?","a":"No, una funció hash criptogràfica és unidireccional."},{"q":"Què distingeix el xifrat simètric?","a":"S’utilitza la mateixa clau secreta per xifrar i desxifrar."}],"links":[],"case":"Defineix regles mínimes de tallafoc per publicar HTTPS sense exposar administració remota."},{"id":18,"title":"Apache, IIS i servidors d’aplicacions","official":"Servidors web i d’aplicacions. Servidors web Apache i Microsoft IIS: Arquitectura, instal·lació i configuració. Servidors d’aplicacions Java: JBoss (WildFly) i Tomcat. Seguretat i administració.","area":"Desenvolupament","priority":"Molt alta","intro":"Un servidor web pot servir contingut estàtic, gestionar TLS i actuar de proxy invers. Un servidor d’aplicacions executa lògica de negoci; Apache httpd, IIS, Tomcat i WildFly tenen funcions diferents.","sections":[{"heading":"Apache httpd","body":"Paràmetres habituals: `Listen`, `ServerName`, `DocumentRoot`, `<VirtualHost>`, `<Directory>`, logs d’accés/error i mòduls. `apachectl configtest` o `httpd -t` valida sintaxi abans de recarregar. La ubicació de fitxers depèn de la distribució."},{"heading":"IIS","body":"Servidor web de Microsoft integrat amb Windows Server, amb sites, application pools, bindings, certificats i logging. Els bindings associen IP/port/host al lloc publicat."},{"heading":"Tomcat i WildFly","body":"Tomcat és sobretot un contenidor de servlets i motor web Java; WildFly és un servidor d’aplicacions Jakarta EE de més abast. No s’han de tractar com a sinònims perfectes."},{"heading":"Seguretat i diagnosi","body":"Minimitzar mòduls exposats, actualitzar, restringir rutes, gestionar identitats, protegir secrets i TLS, revisar logs i monitorar errors 403, 404 i 5xx. Diferenciar error DNS, xarxa, servidor web i backend."}],"schema":["PETICIÓ WEB","Navegador → DNS → HTTPS (443)","Apache/IIS → estàtics o proxy invers","Tomcat/WildFly → lògica Java","Logs + TLS + permisos → seguretat"],"cards":[{"q":"Per a què serveix DocumentRoot a Apache?","a":"Defineix el directori arrel des del qual se serveixen documents, segons configuració."},{"q":"Què fa un VirtualHost?","a":"Permet configuracions de lloc web diferenciades en un mateix servidor."},{"q":"Tomcat és igual que Apache httpd?","a":"No: Tomcat executa aplicacions Java web; httpd és principalment servidor HTTP."}],"links":[{"name":"Manual oficial Apache","url":"https://httpd.apache.org/docs/2.4/"}],"case":"Un web dona HTTP 403 després d’un canvi: revisa `<Directory>`, permisos i log d’errors."},{"id":19,"title":"Virtualització i contenidors","official":"Virtualització i Tecnologies de Contenidors. Conceptes de virtualització de servidors. Contenidors d’aplicacions: arquitectura Docker. Orquestració (Kubernetes). Avantatges en portabilitat i escalabilitat.","area":"Sistemes","priority":"Alta","intro":"Virtualitzar permet executar màquines virtuals aïllades sobre un mateix host. Els contenidors encapsulen aplicacions i dependències però comparteixen el kernel de l’host en els escenaris Linux habituals.","sections":[{"heading":"Virtualització","body":"Hipervisor tipus 1 funciona directament sobre hardware; tipus 2 sobre sistema operatiu host. Una VM inclou sistema operatiu convidat, recursos virtuals i discs virtuals. Snapshot no substitueix backup."},{"heading":"Docker","body":"Imatge: plantilla immutable per capes; contenidor: instància executada; Dockerfile: instruccions de construcció; registry: magatzem d’imatges; volums: persistència. L’aïllament s’implementa amb namespaces i cgroups, entre altres mecanismes."},{"heading":"Kubernetes","body":"Orquestra contenidors mitjançant Pods, Deployments, Services, ConfigMaps i Secrets. Permet escalar rèpliques, distribuir càrrega i refer instàncies amb fallades; no resol automàticament la seguretat de les aplicacions."},{"heading":"Pros i riscos","body":"Eficiència d’ús de recursos, reproduïbilitat i portabilitat, amb riscos de configuració insegura, imatges obsoletes, privilegis excessius i persistència mal definida."}],"schema":["EXECUCIÓ D’APLICACIONS","Host → hipervisor → VM (+SO convidat)","Host Linux → contenidors (+kernel compartit)","Docker → imatge → contenidor → volum","Kubernetes → pods → serveis → escalat"],"cards":[{"q":"Una imatge Docker és el mateix que un contenidor?","a":"No: imatge és la plantilla; contenidor és una instància d’execució."},{"q":"Els contenidors necessiten habitualment un kernel propi complet?","a":"No, comparteixen el kernel de l’host, a diferència d’una VM convencional."},{"q":"Kubernetes és un hipervisor?","a":"No. És una plataforma d’orquestració de contenidors."}],"links":[{"name":"Documentació Docker","url":"https://docs.docker.com/"},{"name":"Conceptes Kubernetes","url":"https://kubernetes.io/docs/concepts/"}],"case":"Proposa com desplegar i actualitzar una petita API municipal contenidoritzada amb dades persistents."},{"id":20,"title":"Serveis al núvol","official":"Serveis al núvol: Serveis més habituals. Tipus de serveis. Avantatges i inconvenients.","area":"Sistemes","priority":"Mitjana","intro":"El cloud presta capacitat informàtica sota demanda a través de xarxa. Distingeix models de servei (què administra el proveïdor) i models de desplegament (on i per a qui).","sections":[{"heading":"Models de servei","body":"IaaS: infraestructura virtual (VM, xarxes, discs); PaaS: entorn gestionat de desenvolupament/explotació; SaaS: aplicació final utilitzada per l’organització. La responsabilitat compartida de seguretat varia en cada model."},{"heading":"Desplegament","body":"Núvol públic, privat, híbrid o comunitari segons definició i règim. Multicloud implica utilitzar diversos proveïdors; no és el mateix que híbrid."},{"heading":"Avantatges","body":"Elasticitat, disponibilitat geogràfica, provisió ràpida, serveis gestionats i pagament per ús quan s’ajusta al consum."},{"heading":"Inconvenients i sector públic","body":"Dependència de proveïdor (vendor lock-in), costos variables, latència, residència de dades, continuïtat i requisits de contractació, ENS i RGPD. Les còpies i el pla de sortida no s’han d’oblidar."}],"schema":["CLOUD","Servei → IaaS / PaaS / SaaS","Desplegament → públic / privat / híbrid","Avantatges → elasticitat / rapidesa","Controls → contracte / dades / ENS / backup"],"cards":[{"q":"SaaS dona control directe del SO del servidor?","a":"Normalment no; el proveïdor gestiona la infraestructura i l’aplicació."},{"q":"Què és el vendor lock-in?","a":"Dependència tecnològica o contractual d’un proveïdor."},{"q":"Una base de dades al núvol elimina obligacions RGPD?","a":"No; cal definir rols, garanties i tractament de dades."}],"links":[],"case":"Avalua allotjar el portal d’activitats municipal en un SaaS enfront d’un servidor propi."},{"id":21,"title":"Enginyeria del programari i Git","official":"Enginyeria del Software: Cicle de vida de les aplicacions. Metodologies àgils (Scrum, Kanban). Control de versions (Git).","area":"Desenvolupament","priority":"Mitjana","intro":"El desenvolupament professional comença en els requisits i inclou disseny, implementació, proves, desplegament i manteniment. Scrum i Kanban organitzen el flux, mentre que Git versiona canvis.","sections":[{"heading":"Cicle de vida","body":"Captura de requisits funcionals/no funcionals, anàlisi, disseny, desenvolupament, proves, lliurament, operació i manteniment. Verificació: construïm bé el producte; validació: construïm el producte adequat."},{"heading":"Scrum","body":"Marc iteratiu amb rols/accountabilities Product Owner, Scrum Master i Developers; Product Backlog, Sprint Backlog i Increment. Esdeveniments: Sprint, Planning, Daily Scrum, Review i Retrospective."},{"heading":"Kanban","body":"Visualització del flux, límits de feina en curs (WIP), mesura de temps de cicle i millora contínua. No obliga a iteracions temporals fixes."},{"heading":"Git","body":"Repositori, commit, branca, merge, conflicte, pull request. `git clone`, `status`, `add`, `commit`, `fetch`, `pull`, `push`, `branch`, `merge`. Un merge conflictiu requereix revisió del contingut, no acceptació cega."}],"schema":["CICLE DE VIDA SOFTWARE","Requisits → disseny → desenvolupament → prova","→ desplegament → manteniment","Scrum: iteracions / increment","Kanban: flux / límit WIP","Git: branches → commits → merge"],"cards":[{"q":"Git i GitHub són el mateix?","a":"No. Git és el sistema de control de versions; GitHub n’és un servei d’allotjament i col·laboració."},{"q":"Què limita el WIP en Kanban?","a":"La quantitat de feina en curs per reduir colls d’ampolla."},{"q":"Qui prioritza el Product Backlog en Scrum?","a":"Product Owner."}],"links":[{"name":"Guia Scrum","url":"https://scrumguides.org/"},{"name":"Documentació Git","url":"https://git-scm.com/docs"}],"case":"Planifica un canvi d’una seu electrònica: requisit, tasques, branca, prova, revisió i desplegament."},{"id":22,"title":"HTML5, CSS3, JavaScript i accessibilitat","official":"Desenvolupament Web (Front-end): HTML5, CSS3, JavaScript. Accessibilitat web (WCAG 2.1). Usabilitat i experiència d’usuari.","area":"Desenvolupament","priority":"Molt alta","intro":"El front-end defineix estructura (HTML), presentació (CSS) i comportament (JavaScript). L’accessibilitat no és opcional en serveis públics: cal facilitar l’ús a persones amb diferents capacitats i tecnologies.","sections":[{"heading":"HTML semàntic","body":"Fer servir `header`, `nav`, `main`, `section`, `article`, `footer`, encapçalaments ordenats, formularis amb `label`, textos alternatius de les imatges quan siguin informatives i enllaços descriptius. HTML no és un llenguatge de programació de propòsit general."},{"heading":"CSS","body":"Selectors d’element (`p`), classe (`.avis`) i ID (`#avis`); cascada, especificitat i herència. Generalment un selector ID té més especificitat que una classe, i una classe més que un selector d’element. Flexbox/Grid serveixen per maquetació adaptable."},{"heading":"JavaScript i DOM","body":"`querySelector`, esdeveniments, variables `let`/`const`, condicionals, arrays, `map` i funcions. El navegador construeix el DOM i el JS pot modificar-lo. Distingir `===` d’`==` i evitar inserció de dades no fiables amb `innerHTML`."},{"heading":"WCAG 2.1","body":"Principis POUR: perceptible, operable, comprensible i robust. Exemples: contrast, navegació per teclat, focus visible, etiquetes, alternatives textuals, errors de formulari intel·ligibles. Les WCAG tenen nivells A, AA i AAA."},{"heading":"UX i proves","body":"Disseny responsive, llenguatge clar, jerarquia visual, formularis curts i proves amb usuaris. El contrast i el color no han de ser l’únic indicador d’estat."}],"schema":["WEB FRONT-END","HTML → estructura i semàntica","CSS → selectors / cascada / responsive","JS → esdeveniments / DOM","WCAG → perceptible / operable / comprensible / robust"],"cards":[{"q":"Quin selector CSS té habitualment més especificitat: #id o .classe?","a":"`#id`, si no intervenen altres regles com `!important` o capes."},{"q":"Què significa POUR?","a":"Perceptible, operable, comprensible i robust (4 principis WCAG)."},{"q":"El CSS afegeix lògica a la base de dades?","a":"No. Defineix presentació; la lògica i les dades corresponen a altres capes."}],"links":[{"name":"Referència web MDN","url":"https://developer.mozilla.org/ca/"},{"name":"WCAG 2.1 oficial","url":"https://www.w3.org/TR/WCAG21/"}],"case":"Repara un formulari de cita prèvia amb camps sense etiquetes, errors invisibles i contrast insuficient."},{"id":23,"title":"Back-end, API REST i SOAP","official":"Desenvolupament Web (Back-end): Arquitectures client-servidor i multicapa. Serveis Web: API REST i SOAP. Formats JSON i XML.","area":"Desenvolupament","priority":"Alta","intro":"El back-end gestiona lògica, autenticació, accés a dades i integració entre serveis. Cal distingir arquitectura, protocol d’intercanvi i format de dades.","sections":[{"heading":"Arquitectura","body":"Client envia peticions; servidor processa i respon. En arquitectura de 3 capes: presentació, lògica de negoci i dades. Les APIs exposen funcionalitat amb contractes i permisos."},{"heading":"REST i HTTP","body":"REST és un estil arquitectònic orientat a recursos; les APIs acostumen a usar HTTP: `GET` consulta, `POST` crea/processa, `PUT` substitueix, `PATCH` modifica parcialment i `DELETE` elimina. Distingir estats HTTP 200, 201, 400, 401, 403, 404, 500."},{"heading":"SOAP","body":"Protocol de missatgeria estructurada en XML, habitualment amb WSDL per descriure serveis. No és una variant de JSON ni simplement un mètode HTTP."},{"heading":"JSON i XML","body":"JSON: objectes, arrays, cadenes, nombres, booleans i null; XML: etiquetes, atributs i estructura jeràrquica. Validar dades d’entrada i controlar permisos independentment del format."},{"heading":"Seguretat API","body":"HTTPS, autenticació/autorizació, validació d’entrades, límits d’ús i registre d’operacions. No exposar credencials ni informació sensible en URL o registres."}],"schema":["APLICACIÓ WEB","Client → HTTP(S) → API","Lògica de negoci → BD / sistemes externs","REST → recursos + verbs HTTP + JSON habitual","SOAP → missatges XML (+ WSDL)"],"cards":[{"q":"Què significa HTTP 403?","a":"Accés prohibit: el servidor entén la petició però la rebutja per permisos/política."},{"q":"Què diferencia PUT i PATCH?","a":"PUT habitualment substitueix la representació del recurs; PATCH en modifica parcialment el contingut."},{"q":"REST exigeix obligatòriament JSON?","a":"No; és un estil arquitectònic, tot i que JSON és molt habitual."}],"links":[{"name":"Documentació HTTP MDN","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP"}],"case":"Dissenya tres endpoints d’API per consultar, crear i actualitzar activitats de l’agenda municipal."},{"id":24,"title":"Tecnologies mòbils i MDM","official":"Tecnologies mòbils i gestió de dispositius. Ecosistema Android i iOS. Desenvolupament d’Apps: natives, híbrides i PWA. Sistemes de gestió de dispositius mòbils (MDM) corporatius.","area":"Desenvolupament","priority":"Mitjana","intro":"En mobilitat corporativa, les dades i les identitats de l’ajuntament poden quedar exposades en telèfons i tauletes. És clau distingir aplicacions i mecanismes de gestió remota.","sections":[{"heading":"Sistemes Android i iOS","body":"Ecosistemes mòbils amb models de permisos, botigues d’aplicacions, sandboxing, actualitzacions i gestió d’identitats. Les polítiques dependran dels models de dispositiu i de la plataforma."},{"heading":"Tipus d’app","body":"Nativa: construïda per a plataforma; híbrida/multiplataforma: comparteix tecnologies i pot empaquetar-se com app; PWA: aplicació web amb capacitats instal·lables/offline segons navegador i permisos. No totes les API natives estan disponibles a una PWA."},{"heading":"MDM/UEM","body":"Inscripció de dispositius, inventari, distribució d’apps, passcode, xifrat, configuració corporativa, gestió de pèrdua, bloqueig i esborrament remot, segons política BYOD/COBO."},{"heading":"Privacitat","body":"Separar dades personals i corporatives, limitar permisos i explicar al personal l’abast del control sobre el dispositiu."}],"schema":["MOBILITAT","Android / iOS → permisos i actualitzacions","App → nativa / híbrida / PWA","MDM → alta / polítiques / apps / esborrament","Seguretat → xifrat / identitat / separació de dades"],"cards":[{"q":"MDM significa què?","a":"Mobile Device Management: gestió de dispositius mòbils."},{"q":"Una PWA necessita obligatòriament publicar-se en una botiga d’apps?","a":"No; es distribueix habitualment com a web instal·lable."},{"q":"MDM permet controlar configuració de seguretat corporativa?","a":"Sí, en funció del dispositiu i de la política aplicada."}],"links":[],"case":"Es perd una tauleta municipal: quins passos de MDM i seguretat s’han de seguir?"},{"id":25,"title":"RPA i hiperautomatització","official":"Automatització de Processos Robòtics (RPA). Concepte i arquitectura. Eines de mercat (UiPath, Power Automate). Identificació de processos automatitzables a l’administració pública. Hiperautomatització.","area":"Desenvolupament","priority":"Mitjana","intro":"RPA automatitza tasques repetitives mitjançant robots de programari; és útil però no substitueix el redisseny de processos ni la comprovació legal de decisions administratives.","sections":[{"heading":"Arquitectura RPA","body":"Robot executa passos sobre interfícies o APIs; orquestrador administra cues, credencials, execucions i registres. Hi ha robots assistits (amb usuari) i desatesos (automàtics)."},{"heading":"Candidats adequats","body":"Tasques repetitives, basades en regles, volum suficient, dades estructurades, procés estable i alta traçabilitat. Errors freqüents: automatitzar pantalles canviants o procediments sense estandarditzar."},{"heading":"UiPath i Power Automate","body":"Plataformes d’automatització amb connectors, fluxos i execució programada. No s’han de confondre necessàriament amb IA: RPA pot seguir regles deterministes."},{"heading":"Hiperautomatització i administració","body":"Combinar RPA, integració API, analítica i IA, amb supervisió humana i registre. Les resolucions administratives automatitzades tenen requisits jurídics específics."}],"schema":["RPA","Seleccionar procés → documentar regles","Crear robot → credencials / flux","Executar → validar excepcions","Registrar / supervisar / millorar","Hiperautomatització = diverses tecnologies coordinades"],"cards":[{"q":"RPA exigeix sempre intel·ligència artificial?","a":"No; pot ser completament basat en regles."},{"q":"Quina tasca és candidata a RPA?","a":"Una tasca repetitiva, previsible, traçable i basada en regles clares."},{"q":"Un robot elimina l’obligació d’auditoria?","a":"No: cal registrar l’execució, errors i responsabilitats."}],"links":[{"name":"Microsoft Power Automate","url":"https://learn.microsoft.com/power-automate/"}],"case":"Descriu una automatització de comprovació de registres, sense emetre resolucions sense control jurídic."},{"id":26,"title":"Disseny de bases de dades","official":"Disseny de bases de dades. Disseny lògic i físic. Model relacional. Normalització.","area":"Dades","priority":"Molt alta","intro":"El disseny de BD transforma requisits del negoci en taules coherents amb restriccions que eviten duplicitats i anomalies. Diferencia conceptual, lògic i físic.","sections":[{"heading":"Fases","body":"Conceptual: entitats, atributs, relacions i cardinalitats, independent de tecnologia. Lògic: taules, columnes, claus i relacions segons model relacional. Físic: índexs, particions, tipus concrets, emmagatzematge i rendiment per a un SGBD."},{"heading":"Claus","body":"PK identifica unívocament registres; FK referencia PK o clau candidata d’una altra taula (segons restriccions); UNIQUE evita duplicats. Cardinalitats 1:1, 1:N, N:M; aquesta última acostuma a resoldre’s amb taula intermèdia."},{"heading":"Normalització","body":"1NF: atributs atòmics i files identificables; 2NF: cap dependència parcial d’una clau composta; 3NF: evitar dependències transitives d’atributs no clau. Objectiu: reduir redundància i anomalies d’inserció, actualització i esborrament."},{"heading":"Integritat","body":"Restriccions `NOT NULL`, `CHECK`, `UNIQUE`, FK; definir comportament de supressió referencial (`RESTRICT`, `CASCADE`, etc.) amb especial prudència en expedients municipals."}],"schema":["REQUISITS → MODEL DE DADES","Conceptual → entitats / relacions / cardinalitats","Lògic → taules / PK / FK / normalització","Físic → índexs / particions / rendiment","Integritat → restriccions"],"cards":[{"q":"Quina fase és independent del SGBD?","a":"El disseny conceptual."},{"q":"Com representaries una relació N:M en model relacional?","a":"Amb una taula d’enllaç que inclogui claus foranes."},{"q":"Per a què serveix una clau forana?","a":"Per relacionar taules i preservar integritat referencial."}],"links":[],"case":"Modela veïns, expedients i tràmits; explica les relacions 1:N i quines claus definiries."},{"id":27,"title":"SGBD, SQL i procediments emmagatzemats","official":"Sistemes gestors de Bases de Dades (ORACLE, PosgreSQL, ...). Consultes i operacions SQL. Procediments emmagetzemats.","area":"Dades","priority":"Molt alta","intro":"SQL és probablement un dels blocs amb millor rendiment per a la pràctica: dominar SELECT, JOIN, agrupacions, modificació i transaccions. Els exemples del PDF d’examen anterior inclouen UPDATE, DELETE, GROUP BY i COUNT.","sections":[{"heading":"Consulta i filtratge","body":"`SELECT ... FROM ... WHERE ... ORDER BY ...`; `WHERE` filtra files abans d’agrupar. `JOIN ... ON` combina taules segons relacions. `INNER JOIN` exclou no coincidents; `LEFT JOIN` manté totes les files de l’esquerra."},{"heading":"Agregació","body":"`COUNT(*)` compta files; `COUNT(col)` ignora NULL. `GROUP BY` crea grups; `HAVING` filtra grups després d’agregar; `ORDER BY ... DESC` ordena resultats descendentment."},{"heading":"Escriptura i transaccions","body":"`INSERT`, `UPDATE`, `DELETE`: sempre revisa el `WHERE` abans de modificar. Transaccions `BEGIN`/`COMMIT`/`ROLLBACK` (sintaxi depèn del SGBD). ACID: atomicitat, consistència, aïllament i durabilitat."},{"heading":"Oracle i PostgreSQL","body":"Comparteixen SQL estàndard però hi ha diferències: `SYSDATE` i `VARCHAR2` són habituals d’Oracle; PostgreSQL admet `CURRENT_DATE`, `RETURNING`, funcions i sintaxi pròpies. Evita assumir portabilitat perfecta."},{"heading":"Procediments","body":"Lògica emmagatzemada al SGBD, amb paràmetres i blocs de codi (PL/SQL a Oracle, PL/pgSQL a PostgreSQL). Útil per encapsular processos i validar permisos."}],"schema":["SQL","SELECT + FROM → WHERE → GROUP BY → HAVING","→ SELECT expressions → ORDER BY (ordre lògic simplificat)","JOIN → combina taules amb ON","DML → INSERT / UPDATE / DELETE","Transacció → COMMIT o ROLLBACK"],"cards":[{"q":"WHERE i HAVING: diferència?","a":"WHERE filtra files abans d’agrupar; HAVING filtra grups un cop agregats."},{"q":"Què retorna COUNT(col) sobre files amb NULL?","a":"No compta els NULL d’aquella columna."},{"q":"Què fa un LEFT JOIN?","a":"Manté totes les files de l’esquerra, incloses les que no troben coincidència a la dreta."}],"links":[{"name":"Manual PostgreSQL SQL","url":"https://www.postgresql.org/docs/current/"},{"name":"Documentació Oracle Database","url":"https://docs.oracle.com/en/database/"}],"case":"Donades taules PERSONES i EXPEDIENTS, escriu el recompte d’expedients per persona, incloent-hi les persones sense expedients."},{"id":28,"title":"Big Data i govern de la dada","official":"Big Data i Analítica de Dades. Arquitectures de processament (Hadoop, Spark). Data Lakes vs. Data Warehouses. Govern de la dada en el sector públic.","area":"Dades","priority":"Mitjana","intro":"Big Data descriu reptes de tractar grans volums, varietat i velocitat de dades. La seva utilitat depèn de qualitat, governança, drets i finalitat.","sections":[{"heading":"Conceptes","body":"Les 3 V clàssiques són volum, velocitat i varietat; sovint s’hi afegeix veracitat i valor. Processament per lots (batch) o en flux (streaming)."},{"heading":"Hadoop i Spark","body":"Hadoop designa un ecosistema de dades distribuïdes amb HDFS i eines de processament; Spark és motor distribuït amb APIs per SQL, dades i altres càrregues. No són bases de dades relacionals equivalents a PostgreSQL."},{"heading":"Lake i warehouse","body":"Data lake desa dades en formats diversos i menys transformats, amb govern necessari; data warehouse integra dades estructurades, modelades i preparades per a analítica. En molts entorns coexisteixen o es combinen."},{"heading":"Govern de la dada","body":"Catàleg, qualitat, propietari de dades, metadades, retenció, traçabilitat, classificació, seguretat i privacitat. En sector públic: minimització, finalitat, informació pública i reutilització quan sigui legal."}],"schema":["BIG DATA","Captura → ingestió batch/stream","Emmagatzematge → lake / warehouse","Processament → Hadoop / Spark","Govern → qualitat / metadades / permisos","Consum → analítica / BI / decisions"],"cards":[{"q":"Data lake i data warehouse són idèntics?","a":"No; el lake pot contenir dades menys estructurades i el warehouse les modela per anàlisi."},{"q":"Spark és només un sistema de fitxers?","a":"No; és un motor de processament distribuït."},{"q":"Què és la traçabilitat de dades?","a":"Saber-ne origen, transformacions i usos al llarg del cicle de vida."}],"links":[],"case":"Defineix un mínim de metadades per a un conjunt municipal obert d’estadístiques de mobilitat."},{"id":29,"title":"Business Intelligence i quadres de comandament","official":"Intel·ligència de negoci: Quadres de comandament integral, sistemes de suport a les decisions, sistemes d’informació executiva i magatzem de dades.","area":"Dades","priority":"Mitjana","intro":"La intel·ligència de negoci converteix dades en indicadors i coneixement per decidir. Cal distingir quadre de comandament, DSS, EIS i warehouse.","sections":[{"heading":"Cicle BI","body":"Fonts → ETL/ELT → magatzem de dades → model semàntic → indicadors → visualització → decisió. Les mètriques han de tenir definicions estables, responsables i periodicitat."},{"heading":"Quadre de comandament integral","body":"El Balanced Scorecard estructura objectius i indicadors en perspectives (financera, clients/usuaris, processos interns, aprenentatge/creixement) adaptables al sector públic. No és només una pantalla de gràfics."},{"heading":"DSS i EIS","body":"DSS dona suport a problemes de decisió i escenaris; EIS proporciona informació agregada per a direcció. La informació executiva no ha de revelar dades personals innecessàries."},{"heading":"Indicadors","body":"KPI útil = rellevant, definit, mesurable i accionable. Diferenciar nombre absolut, percentatge, taxa i tendència; mirar qualitat del denominador i període."}],"schema":["BI","Dades → ETL/ELT → Data warehouse","→ KPI → quadre de comandament","DSS → escenaris i decisions","EIS → visió de direcció","Govern → qualitat / permisos"],"cards":[{"q":"Què és un KPI?","a":"Indicador clau de rendiment que mesura avenç respecte d’un objectiu."},{"q":"DSS i EIS tenen la mateixa finalitat exacta?","a":"No: DSS suporta decisions/escenaris; EIS aporta visió executiva agregada."},{"q":"Un data warehouse acostuma a integrar dades de diverses fonts?","a":"Sí, per facilitar consulta analítica coherent."}],"links":[],"case":"Proposa 4 KPI per al servei municipal de suport TIC, amb definició i periodicitat."},{"id":30,"title":"Intel·ligència artificial i Reglament d’IA","official":"Intel·ligència Artificial (IA). Fonaments, Machine Learning i Deep Learning. IA Generativa (LLMs). Ètica, biaixos i el reglament europeu d’IA (AI Act).","area":"Dades","priority":"Molt alta","intro":"La IA inclou sistemes que produeixen prediccions, recomanacions o continguts. El Reglament (UE) 2024/1689 estableix un enfocament basat en el risc, amb calendari d’aplicació esglaonat.","sections":[{"heading":"Nivells tècnics","body":"ML: aprèn patrons a partir de dades; deep learning: models amb xarxes neuronals profundes; generativa: produeix text, imatge o altres continguts. Un LLM prediu seqüències de tokens i pot al·lucinar dades no comprovades."},{"heading":"Entrenament i avaluació","body":"Conjunts d’entrenament, validació i prova; sobreajustament, dades esbiaixades i necessitat de mètriques adequades. Classificació i regressió són tasques diferents."},{"heading":"Ètica i riscos","body":"Biaixos discriminadors, opacitat, fuites de dades, errors i dependència. En administració: base jurídica, proporcionalitat, supervisió humana i transparència d’ús quan correspongui."},{"heading":"AI Act","body":"Classifica sistemes amb prohibicions, requisits per a sistemes d’alt risc i obligacions de transparència, entre d’altres. El calendari és gradual i ha estat objecte de propostes de modificació; cal comprovar la versió vigent en preparar l’examen."},{"heading":"Sector públic","body":"No introduir dades personals o confidencials en serveis IA sense habilitació, garanties i instruccions corporatives. Cal validar resultats abans d’incorporar-los a resolucions o informació ciutadana."}],"schema":["INTEL·LIGÈNCIA ARTIFICIAL","IA → ML → deep learning","Generativa → LLM / contingut","Riscos → biaix / error / privacitat","AI Act → usos prohibits / alt risc / transparència","Administració → supervisió + legalitat"],"cards":[{"q":"Deep learning és un subconjunt de machine learning?","a":"Sí."},{"q":"Un text generat per LLM és necessàriament correcte?","a":"No; cal contrastar-lo i comprovar fonts."},{"q":"Com s’estructura l’AI Act?","a":"Principalment per nivells de risc i per obligacions específiques segons ús i tipus de sistema."}],"links":[{"name":"Reglament europeu d’IA (text oficial)","url":"https://eur-lex.europa.eu/eli/reg/2024/1689/oj"}],"case":"Analitza riscos d’un assistent IA per orientar ciutadans sense automatitzar una decisió administrativa."},{"id":31,"title":"Internet de les coses i Smart Cities","official":"Internet de les Coses (IoT) i Smart Cities. Arquitectura IoT i protocols (MQTT, LoRaWAN). Aplicacions en la gestió municipal (enllumenat, residus). Seguretat IoT.","area":"Xarxes","priority":"Mitjana","intro":"IoT combina sensors/actuadors, xarxes, passarel·les i plataformes de dades. Una smart city aplica aquestes tecnologies a serveis municipals amb criteris de sostenibilitat, interoperabilitat i seguretat.","sections":[{"heading":"Arquitectura","body":"Dispositiu capta o actua → connectivitat → gateway/edge → plataforma → quadre de comandament / automatització. Les dades de sensors necessiten segell temporal, identificador i qualitat."},{"heading":"MQTT i LoRaWAN","body":"MQTT és protocol de missatgeria publicació/subscripció amb broker; LoRaWAN és tecnologia de xarxa de baixa potència i llarg abast, sovint útil per sensors amb petits missatges. No són conceptes equivalents."},{"heading":"Usos municipals","body":"Enllumenat adaptatiu, mesura ambiental, aparcament, detecció de plens en contenidors, reg intel·ligent i consums. Dissenyar indicadors abans de desplegar sensors."},{"heading":"Seguretat","body":"Inventari, identitats úniques, canvis de credencials per defecte, actualització segura, segmentació i cicle de vida. Evitar que un sensor compromès permeti arribar a sistemes interns crítics."}],"schema":["SMART CITY / IOT","Sensor/actuador → xarxa (LoRaWAN, Wi-Fi, etc.)","→ gateway / plataforma → dades","→ regles / BI / servei municipal","MQTT → missatges pub/sub via broker","Seguretat → identitats / firmware / segmentació"],"cards":[{"q":"MQTT és un tipus de sensor?","a":"No, és un protocol de missatgeria pub/sub."},{"q":"LoRaWAN és adequat per vídeo continu d’alta definició?","a":"En general no; prioritza baix consum i missatges petits."},{"q":"Per què cal segmentar IoT?","a":"Per limitar moviments laterals si un dispositiu és compromès."}],"links":[],"case":"Planteja un sistema per detectar contenidors plens amb sensor, xarxa, plataforma i alertes."},{"id":32,"title":"Gestió de projectes TIC i contractació","official":"Gestió de projectes TIC i Contractació Pública. Metodologies tradicionals vs. Àgils. La Llei de Contractes (LCSP) aplicada a les TIC: plecs tècnics i administratius.","area":"Desenvolupament","priority":"Mitjana","intro":"En projectes informàtics públics s’han de gestionar abast, temps, recursos, riscos, contractació i recepció. Metodologia d’execució i procediment de contractació són aspectes diferents.","sections":[{"heading":"Projectes tradicionals","body":"Enfocament predictiu: fases planificades, requisits inicials, fites i control de canvis. Pot encaixar quan l’abast és estable i verificable."},{"heading":"Àgils","body":"Lliuraments iteratius i priorització contínua amb retiment de comptes. La flexibilitat no eximeix de respectar objecte, pressupost i modificacions contractuals permeses."},{"heading":"Plecs","body":"PCAP: condicions administratives, solvència, criteris, obligacions i penalitats. PPT: requisits funcionals i no funcionals, SLA, interoperabilitat, seguretat, accessibilitat, proves i lliurables."},{"heading":"Seguiment i recepció","body":"Definir criteris objectius d’acceptació, documentar canvis, controlar terminis i garantir reversibilitat, exportació de dades, titularitat/llicències i continuïtat del servei."}],"schema":["PROJECTE TIC PÚBLIC","Necessitat → requisits → plecs PCAP/PPT","Licitació → adjudicació","Execució → fites / canvis / riscos","Proves → recepció / SLA","Manteniment → reversibilitat"],"cards":[{"q":"PCAP i PPT: diferència?","a":"PCAP regula clàusules administratives; PPT defineix prescripcions tècniques."},{"q":"Un projecte àgil pot ignorar la LCSP?","a":"No; la metodologia no substitueix els requisits contractuals."},{"q":"Què és un SLA?","a":"Acord de nivell de servei amb objectius mesurables, com temps de resposta o disponibilitat."}],"links":[{"name":"Llei de contractes","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902"}],"case":"Redacta requisits tècnics mesurables per mantenir el portal web municipal sense citar una marca exclusiva."},{"id":33,"title":"ITIL i gestió de serveis TIC","official":"Models de referència i bones pràctiques en la gestió de serveis TIC. Suport a usuaris, gestió d’incidències, problemes, peticions (ITIL).","area":"Sistemes","priority":"Alta","intro":"ITIL proporciona pràctiques per prestar serveis de tecnologia de forma controlada. El test confon sovint incidència, problema, petició de servei i canvi.","sections":[{"heading":"Service Desk","body":"Punt de contacte amb usuaris: registra, classifica, prioritza, comunica, escala i verifica resolució. Ha de conservar traçabilitat de tiquets i dades personals mínimes."},{"heading":"Incidència","body":"Interrupció no prevista o degradació d’un servei; objectiu: restaurar-lo ràpidament. Prioritat sovint resultat d’impacte i urgència, no només de l’ordre d’arribada."},{"heading":"Problema i petició","body":"Problema: causa o potencial causa d’una o diverses incidències; la seva gestió intenta eliminar recurrència. Petició de servei: sol·licitud estàndard (alta d’usuari, instal·lació autoritzada, accés)."},{"heading":"Canvis, coneixement i SLA","body":"Canvi: addició, modificació o retirada d’element que pot afectar serveis. Documentar solucions conegudes, base de coneixement, SLA i KPI com temps mitjà de resolució (MTTR)."}],"schema":["ITIL / SERVEIS","Usuari → Service Desk → tiquet","Incidència → restaurar servei","Problema → analitzar causa arrel","Petició → servei estàndard autoritzat","Canvi → avaluar riscos / aprovar / executar"],"cards":[{"q":"Incidència i problema són sinònims?","a":"No: incidència és interrupció/degradació; problema és la causa o causa potencial."},{"q":"L’alta d’un compte aprovada és una incidència?","a":"Habitualment és una petició de servei."},{"q":"Quins dos factors solen determinar prioritat?","a":"Impacte i urgència."}],"links":[{"name":"Referència ITIL / AXELOS","url":"https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"}],"case":"Diversos usuaris perden accés a la xarxa: registra incidència, prioritza, escala i decideix quan obrir problema."},{"id":34,"title":"Documents i expedient electrònic","official":"Funcionament electrònic del sector públic. Expedient electrònic, Arxiu electrònic, document electrònic. Còpies d’aquests i fonaments tecnològics que suporten el seu valor legal.","area":"Administració digital","priority":"Molt alta","intro":"La gestió electrònica municipal exigeix documents íntegres, autèntics, disponibles i traçables. Cal distingir document, expedient, còpia autèntica i arxiu; són conceptes relacionats però no idèntics.","sections":[{"heading":"Document electrònic","body":"Informació en forma electrònica identificable i susceptible de tractament. Un document administratiu electrònic incorpora requisits de validesa, identificació, referència temporal quan pertoqui, metadades i signatures/sistemes admesos."},{"heading":"Expedient electrònic","body":"Conjunt ordenat de documents i actuacions que serveixen d’antecedent i fonament a la resolució, amb índex electrònic autenticat en els casos i formes previstos legalment. No inclou necessàriament la informació auxiliar o de suport."},{"heading":"Còpies autèntiques","body":"Les expedides per òrgans competents amb garanties tècniques i procedimentals tenen efectes de còpia autèntica. Una fotografia, escaneig informal o PDF signat pel ciutadà no equival automàticament a còpia autèntica administrativa."},{"heading":"Arxiu i preservació","body":"Conservació electrònica amb metadades, integritat, control d’accés, formats perdurables, polítiques de conservació, migració i eliminació documentada quan sigui possible legalment."},{"heading":"Fonaments legals","body":"Llei 39/2015, Llei 40/2015, RD 203/2021, ENS i ENI. Validesa jurídica no és sinònim de només tenir un certificat digital visible al PDF."}],"schema":["GESTIÓ DOCUMENTAL","Document + metadades + integritat","→ tràmits → expedient / índex","→ resolució / notificació","→ arxiu electrònic / preservació","Còpia autèntica → garanties de l’òrgan competent"],"cards":[{"q":"Una carpeta de PDFs és sempre un expedient electrònic vàlid?","a":"No; ha de complir requisits normatius d’estructura, integritat, índex quan pertoqui i metadades."},{"q":"Un escaneig personal és automàticament còpia autèntica?","a":"No; ha de generar-se amb les garanties i competència establertes."},{"q":"Quina finalitat té l’índex electrònic?","a":"Garantir organització i integritat del conjunt documental en els termes legals."}],"links":[{"name":"LPAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565"},{"name":"RD 203/2021","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-5032"},{"name":"ENI","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331"}],"case":"Explica el circuit: entrada en paper → digitalització vàlida → registre → expedient → notificació → arxiu."},{"id":35,"title":"Identitat, certificats i signatura digital","official":"Identitat i Signatura Digital: Reglament eIDAS. Tipus de signatura electrònica. Certificats digitals (T-CAT, idCAT). Cl@ve i VÀLID.","area":"Administració digital","priority":"Molt alta","intro":"Identificar una persona i signar un document són operacions diferents. Els certificats i sistemes d’identitat proporcionen garanties tècniques i jurídiques segons el seu tipus i ús.","sections":[{"heading":"eIDAS","body":"Marc europeu de la identificació electrònica i serveis de confiança, amb modificacions posteriors. Distingir signatura simple, avançada i qualificada segons requisits normatius. La qualificada té efecte jurídic equivalent a signatura manuscrita a la UE."},{"heading":"Certificats","body":"Certificat electrònic vincula dades de validació d’una signatura a una persona o entitat, segons tipus. La clau privada ha d’estar protegida; el certificat públic no és la clau privada."},{"heading":"T-CAT i idCAT","body":"T-CAT és identificació/signatura per a empleats públics de les administracions catalanes; idCAT Certificat s’orienta a ciutadania. Els sistemes s’utilitzen amb els permisos i el context corresponents."},{"heading":"Cl@ve i VÀLID","body":"Cl@ve és sistema estatal d’identificació electrònica; VÀLID és servei del Consorci AOC per integrar diferents mecanismes d’identificació a les seus i tràmits. No equivalen automàticament a una signatura qualificada."},{"heading":"Validació","body":"Verificar vigència, cadena de confiança, revocació i integritat; en documents signats, distingir signatura i segell electrònic d’entitat."}],"schema":["IDENTITAT I SIGNATURA","Identificació → qui és?","Autenticació → prova d’identitat","Signatura → voluntat + integritat + vincle","Certificat → identitat + clau pública","eIDAS → simple / avançada / qualificada"],"cards":[{"q":"Certificat i signatura són el mateix?","a":"No; el certificat és un element de confiança que pot utilitzar-se en signatura."},{"q":"Quina signatura equival jurídicament a manuscrita a la UE?","a":"La signatura electrònica qualificada."},{"q":"VÀLID és un SGBD?","a":"No. És un servei d’integració de mecanismes d’identificació electrònica."}],"links":[{"name":"eIDAS, Reglament UE 910/2014","url":"https://eur-lex.europa.eu/eli/reg/2014/910/oj"},{"name":"Consorci AOC","url":"https://www.aoc.cat/serveis/"}],"case":"Una persona pot accedir amb Cl@ve però falla la signatura d’un tràmit: separa identificació d’acte de signatura."},{"id":36,"title":"Serveis d’administració electrònica AOC","official":"Administració Electrònica a Catalunya: Els seveis del Consorci AOC. Serveis disponibles: e-TRAM, e-NOTUM, e-FACT, Via Oberta, EACAT, etc.","area":"Administració digital","priority":"Molt alta","intro":"L’AOC proporciona serveis compartits per a administracions catalanes. Les preguntes es basen sovint en relacionar el nom del servei amb la seva funció exacta.","sections":[{"heading":"e-TRAM i e-NOTUM","body":"e-TRAM: tramitació electrònica per als ciutadans i ens locals; e-NOTUM: servei de notificacions i comunicacions electròniques. Una sol·licitud de tràmit i una notificació no són la mateixa operació."},{"heading":"e-FACT i EACAT","body":"e-FACT: punt general d’entrada de factures electròniques; EACAT: espai de tramitació i comunicació entre administracions catalanes, no portal general del ciutadà."},{"heading":"Via Oberta","body":"Permet consultar o verificar dades i documents entre administracions amb justificació legal i permisos, per evitar exigir informació ja disponible quan sigui procedent."},{"heading":"Altres serveis","body":"VÀLID per a integració d’identificació; idCAT en identitat ciutadana; serveis de signatura, interoperabilitat, registre i transparència segons cartera actual. Els productes poden evolucionar: consultar sempre fitxes AOC vigents."},{"heading":"Casos municipals","body":"Alta d’una instància, obtenció de dades de padró via servei autoritzat, notificació a interessat, factura de proveïdor i comunicació amb Generalitat són cinc processos diferents."}],"schema":["AOC → QUIN SERVEI?","e-TRAM → tràmits ciutadans","e-NOTUM → notificacions electròniques","e-FACT → factura electrònica","Via Oberta → dades interoperables","EACAT → tramitació entre administracions","VÀLID → integració identificació"],"cards":[{"q":"On rebria una notificació electrònica municipal?","a":"Mitjançant e-NOTUM, si l’ens n’utilitza el servei i correspon al procediment."},{"q":"Què facilita Via Oberta?","a":"Intercanvi/consulta legítima de dades entre administracions."},{"q":"EACAT és portal general de tràmits de ciutadania?","a":"No; serveix especialment a les relacions i tramitacions entre ens públics."}],"links":[{"name":"Catàleg oficial serveis AOC","url":"https://www.aoc.cat/serveis/"}],"case":"Relaciona cinc expedients reals amb e-TRAM, e-NOTUM, e-FACT, Via Oberta i EACAT."},{"id":37,"title":"Transparència i dades obertes","official":"Transparència i Dades Obertes (Open Data). Llei 19/2014 de transparència. La reutilització de la informació del sector públic (RISP). Formats estàndard i interoperabilitat semàntica.","area":"Administració digital","priority":"Molt alta","intro":"La transparència exigeix publicitat activa i dret d’accés, però no una publicació indiscriminada de dades personals. Les dades obertes i la reutilització hi estan vinculades, encara que tenen requisits propis.","sections":[{"heading":"Publicitat activa","body":"Deure de publicar informació d’organització, activitat pública, gestió econòmica, contractació i altres matèries. La informació ha de ser accessible, actualitzada i comprensible segons la normativa."},{"heading":"Dret d’accés","body":"Qualsevol persona pot sol·licitar informació pública sense haver de motivar la petició, amb límits legals i ponderació. A Catalunya el termini general per resoldre és d’un mes, amb regles de suspensió/ampliació quan pertoqui."},{"heading":"Protecció de dades","body":"Cal examinar dades especialment protegides, dades identificatives i accessos parcials; l’existència d’un expedient no autoritza a publicar-lo íntegrament a Internet."},{"heading":"RISP i formats","body":"Reutilitzar és emprar informació pública amb finalitats diferents de les de la seva missió inicial, en condicions legals. Prioritzar CSV, JSON, XML i metadades, llicències clares i formats tractables per màquina quan escaigui."},{"heading":"Interoperabilitat semàntica","body":"Acordar significat de camps, vocabularis, codis, identificadors i unitats perquè diversos organismes puguin interpretar dades igual."}],"schema":["TRANSPARÈNCIA","Publicitat activa → publica sense sol·licitud","Dret d’accés → petició + límits + resolució","Open Data → dades reutilitzables","RISP → condicions de reutilització","Semàntica → mateix significat de les dades"],"cards":[{"q":"Cal justificar una sol·licitud d’accés?","a":"No és obligatori motivar-la."},{"q":"Es poden publicar totes les dades personals per transparència?","a":"No; s’apliquen límits, ponderació i normativa de protecció de dades."},{"q":"Què aporta la interoperabilitat semàntica?","a":"Que sistemes diferents interpretin camps i dades amb el mateix significat."}],"links":[{"name":"Llei catalana 19/2014","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=680124"},{"name":"Llei 37/2007 sobre reutilització","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-19814"}],"case":"Decideix quines columnes publicar en un CSV d’activitats subvencionades, evitant dades personals innecessàries."},{"id":38,"title":"Esquema Nacional de Seguretat i OWASP","official":"L’Esquema nacional de seguretat (ENS). Reial Decret 3/2010. Principis bàsics de ciberseguretat en aplicacions web (OWASP).","area":"Administració digital","priority":"Molt alta","intro":"Atenció a les bases: el tema cita literalment el RD 3/2010, però està derogat pel RD 311/2022, norma que també apareix a l’annex II. Per a contingut vigent s’ha d’estudiar el RD 311/2022 i no presentar el 3/2010 com a vigent.","sections":[{"heading":"Finalitat ENS","body":"Estableix principis bàsics, requisits mínims i mesures per protegir informació i serveis de les entitats dins del seu àmbit. Vincula seguretat a riscos i exigeix responsabilitats, política i millora contínua."},{"heading":"Principis","body":"Seguretat integral; gestió de riscos; prevenció, detecció, resposta i conservació; existència de línies de defensa; vigilància contínua; reavaluació periòdica; diferenciació de responsabilitats."},{"heading":"Categories","body":"Bàsica, mitjana i alta segons valoració de dimensions de seguretat dels sistemes, amb requisits proporcionats. No es tracta de classificar només per nombre d’usuaris."},{"heading":"OWASP","body":"OWASP Top 10 resumeix riscos comuns web: control d’accés trencat, falles criptogràfiques, injecció, disseny insegur, configuració insegura, components vulnerables, entre altres; les categories depenen de l’edició consultada."},{"heading":"Mesures web","body":"Validació i escapament de sortides, consultes parametritzades, autenticació/MFA, gestió de sessions, capçaleres segures, TLS, control de secrets, actualitzacions i registres. Evitar SQL concatenat amb inputs d’usuari."}],"schema":["ENS + OWASP","ENS → governança / riscos / mesures / auditoria","Categories → bàsica / mitjana / alta","Defensa → prevenir / detectar / respondre / recuperar","OWASP → vulnerabilitats web","Controls → ACL / paràmetres SQL / TLS / pedaços"],"cards":[{"q":"Quin RD de l’ENS està vigent?","a":"RD 311/2022; el RD 3/2010 citat en l’enunciat de temari està derogat."},{"q":"Què evita una consulta SQL parametritzada?","a":"Redueix el risc d’injecció SQL quan s’utilitza correctament."},{"q":"L’ENS és només un antivirus obligatori?","a":"No; és un marc complet de govern, risc i controls de seguretat."}],"links":[{"name":"ENS vigent: RD 311/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-7191"},{"name":"OWASP Top 10","url":"https://owasp.org/www-project-top-ten/"}],"case":"Un formulari web concatena text d’usuari en una consulta SQL: explica risc, prevenció i registre d’incidents."},{"id":39,"title":"Esquema Nacional d’Interoperabilitat","official":"L’Esquema nacional d’interoperabilitat (ENI). Reial Decret 4/2010. Normativa d’intercanvi de dades.","area":"Administració digital","priority":"Alta","intro":"L’ENI pretén que les administracions i els sistemes puguin treballar conjuntament i compartir dades i documents amb garanties de significat, format i gestió.","sections":[{"heading":"Finalitat i dimensions","body":"Interoperabilitat organitzativa (procediments i acords), semàntica (significat de dades), tècnica (protocols i formats) i temporal (perdurabilitat i recuperació de la informació)."},{"heading":"RD 4/2010 i NTI","body":"El RD 4/2010 estableix principis i criteris generals; les Normes Tècniques d’Interoperabilitat (NTI) concreten document electrònic, expedient, còpies, catàlegs d’estàndards i altres aspectes."},{"heading":"Metadades i formats","body":"Cal identificar documents, gestionar metadades mínimes, signatura/intercanvi i preservació. L’elecció de formats oberts o estàndards facilita independència i interoperabilitat."},{"heading":"Intercanvi de dades","body":"No confondre possibilitat tècnica amb autorització jurídica. Cada consulta requereix finalitat, base legal i permisos; registrar qui consulta què i per què segons el règim aplicable."}],"schema":["ENI","Organitzativa → processos / acords","Semàntica → significat de camps","Tècnica → formats / APIs / protocols","Temporal → preservació a llarg termini","NTI → documents / expedients / intercanvi"],"cards":[{"q":"Quin RD regula l’ENI?","a":"Reial decret 4/2010."},{"q":"Semàntica vol dir només que dos sistemes comparteixin PDF?","a":"No; significa que comprenen igualment les dades i el seu significat."},{"q":"Poder consultar una dada vol dir tenir dret a fer-ho?","a":"No; cal habilitació jurídica i control de permisos."}],"links":[{"name":"ENI: RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331"}],"case":"Descriu com intercanviar dades de padró amb un organisme autoritzat, amb garanties tècniques i jurídiques."},{"id":40,"title":"Protecció de dades personals i RGPD","official":"La protecció de dades de caràcter personal. El Reglament General de Protecció de dades (RGPD) a l’administració local. Conceptes bàsics i la seva adequació. Ordinadors personals. Arquitectura. Tipus i característiques. Instal·lació i configuració de components de maquinari.","area":"Administració digital","priority":"Alta","intro":"El RGPD protegeix dades de persones físiques i imposa principis i responsabilitats al tractament. Les bases inclouen al final d’aquest tema una repetició de la descripció del tema 9 (maquinari); es conserva a l’enunciat literal i cal comprovar amb el tribunal si és una errada material.","sections":[{"heading":"Conceptes","body":"Dada personal: informació d’una persona física identificada o identificable. Tractament: qualsevol operació sobre dades. Responsable decideix finalitats i mitjans; encarregat tracta dades per compte del responsable."},{"heading":"Principis","body":"Licitud, lleialtat i transparència; limitació de finalitat; minimització; exactitud; limitació de conservació; integritat/confidencialitat; responsabilitat proactiva."},{"heading":"Bases jurídiques i drets","body":"En administració pública sovint el tractament es basa en missió d’interès públic/exercici de poders públics o obligació legal, no en consentiment. Drets: accés, rectificació, supressió, limitació, portabilitat i oposició, amb règims i límits."},{"heading":"Organització","body":"Registre d’activitats, informació als afectats, contractes amb encarregats, avaluació d’impacte quan pertoqui, notificació de bretxes en terminis establerts i Delegat de Protecció de Dades segons les obligacions legals."},{"heading":"Maquinari repetit en les bases","body":"El text oficial repeteix literalment el contingut d’ordinadors personals a la fi del tema 40. Repassa també el tema 9, però mantén clar que és una reiteració documental i no un nou desenvolupament del RGPD."}],"schema":["RGPD","Dada → finalitat + base jurídica","Responsable ↔ encarregat","Principis → minimització / seguretat / transparència","Drets → ARSLOP (accés, rectificació, supressió, limitació, oposició, portabilitat)","Govern → DPD / riscos / bretxes"],"cards":[{"q":"L’Ajuntament necessita sempre consentiment per tractar dades?","a":"No; moltes operacions es basen en obligació legal o missió d’interès públic."},{"q":"Qui decideix finalitats i mitjans del tractament?","a":"El responsable del tractament."},{"q":"Una fotografia identificable pot ser dada personal?","a":"Sí, si permet identificar una persona física."}],"links":[{"name":"RGPD text oficial","url":"https://eur-lex.europa.eu/eli/reg/2016/679/oj"},{"name":"Llei orgànica 3/2018","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673"}],"case":"Determina si es pot publicar a la web municipal un llistat d’expedients amb DNI complets i com anonimitzar-lo."}];